<?php
require __DIR__.'/includes/bootstrap.php';$pdo=db_or_null();if(!$pdo||!installed()){http_response_code(404);exit('File unavailable.');}
if(isset($_GET['case'])){$s=$pdo->prepare('SELECT file_path,original_filename,mime_type,NULL source_url FROM cases WHERE id=? AND is_published=1');$s->execute([(int)$_GET['case']]);}else{$s=$pdo->prepare('SELECT file_path,original_filename,mime_type,source_url FROM documents WHERE id=? AND is_published=1');$s->execute([(int)($_GET['id']??0)]);}$r=$s->fetch();if(!$r){http_response_code(404);exit('File unavailable.');}if(!$r['file_path']){if($r['source_url']){header('Location: '.$r['source_url']);exit;}http_response_code(404);exit('No attached file.');}global $config;$base=realpath($config['upload']['path']);$path=realpath($config['upload']['path'].'/'.ltrim($r['file_path'],'/'));if(!$base||!$path||!str_starts_with($path,$base.DIRECTORY_SEPARATOR)||!is_file($path)){http_response_code(404);exit('File unavailable.');}$name=preg_replace('/[^A-Za-z0-9._ -]/','_',basename($r['original_filename']?:$path));header('Content-Type: '.($r['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.$name.'"');header('X-Content-Type-Options: nosniff');readfile($path);
